// app/api/customer/orders/archive/route.ts — Customer Order Archival API (Package V04)
// Allows legitimate customers to hide terminal orders from their active purchase history.
// User-specific visibility preference only; preserves all financial, operational, and inventory records.

import { NextRequest, NextResponse } from "next/server";
import { verifySessionToken } from "@/src/auth/service";
import { extractCookieMap, extractSessionToken } from "@/app/lib/auth";
import { CustomerPurchaseService } from "@/src/services/customer-purchase.service";

const NO_CACHE_HEADERS = {
  "Cache-Control": "private, no-store, no-cache, must-revalidate",
  "Pragma": "no-cache",
};

function getAuthenticatedUserId(request: NextRequest): string | null {
  const token =
    extractSessionToken(request) ||
    request.cookies?.get?.("xeurie_session_v2")?.value ||
    extractCookieMap(request)["xeurie_session_v2"];

  if (!token) return null;
  const payload = verifySessionToken(token);
  return payload?.userId || null;
}

export async function POST(request: NextRequest) {
  const userId = getAuthenticatedUserId(request);
  if (!userId) {
    return NextResponse.json(
      { success: false, error: "UNAUTHORIZED", message: "Customer authentication required." },
      { status: 401, headers: NO_CACHE_HEADERS }
    );
  }

  let body: any = {};
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { success: false, error: "INVALID_JSON", message: "Invalid request payload." },
      { status: 400, headers: NO_CACHE_HEADERS }
    );
  }

  const orderCodes = body?.orderCodes || body?.orderIds;
  if (Array.isArray(orderCodes)) {
    const result = await CustomerPurchaseService.bulkArchiveOrders(userId, orderCodes);
    if (result.migrationPending) {
      return NextResponse.json(
        { success: false, error: "MIGRATION_PENDING", message: "Customer archival table pending forward migration (057)." },
        { status: 503, headers: NO_CACHE_HEADERS }
      );
    }
    return NextResponse.json(
      {
        success: true,
        removed: result.removed,
        blocked: result.blocked,
        failed: result.failed,
        totalRequested: result.totalRequested,
        removedCount: result.removedCount,
        blockedCount: result.blockedCount,
        failedCount: result.failedCount,
        message: `${result.removedCount} removed${result.blockedCount > 0 ? `, ${result.blockedCount} couldn’t be removed` : ""}`,
      },
      { headers: NO_CACHE_HEADERS }
    );
  }

  const orderCode = body?.orderCode || body?.orderId;
  if (!orderCode || typeof orderCode !== "string") {
    return NextResponse.json(
      { success: false, error: "MISSING_ORDER_CODE", message: "orderCode is required." },
      { status: 400, headers: NO_CACHE_HEADERS }
    );
  }

  const result = await CustomerPurchaseService.archiveOrder(userId, orderCode.trim());
  if (!result.success) {
    const status = result.code === "MIGRATION_PENDING" || result.error?.includes("migration") ? 503 : 400;
    return NextResponse.json(
      { success: false, error: result.code || "ARCHIVE_FAILED", message: result.error },
      { status, headers: NO_CACHE_HEADERS }
    );
  }

  return NextResponse.json(
    {
      success: true,
      isArchived: true,
      orderCode: result.orderCode,
      message: "Order removed from active purchase history.",
    },
    { headers: NO_CACHE_HEADERS }
  );
}

export async function DELETE(request: NextRequest) {
  const userId = getAuthenticatedUserId(request);
  if (!userId) {
    return NextResponse.json(
      { success: false, error: "UNAUTHORIZED", message: "Customer authentication required." },
      { status: 401, headers: NO_CACHE_HEADERS }
    );
  }

  let body: any = {};
  try {
    body = await request.json();
  } catch {}

  const orderCodes = body?.orderCodes || body?.orderIds;
  if (Array.isArray(orderCodes)) {
    const result = await CustomerPurchaseService.bulkUnarchiveOrders(userId, orderCodes);
    if (result.migrationPending) {
      return NextResponse.json(
        { success: false, error: "MIGRATION_PENDING", message: "Archival persistence unavailable (forward migration 057 pending)." },
        { status: 503, headers: NO_CACHE_HEADERS }
      );
    }
    return NextResponse.json(
      {
        success: true,
        restored: result.restored,
        failed: result.failed,
        totalRequested: result.totalRequested,
        restoredCount: result.restoredCount,
        failedCount: result.failedCount,
        message: `${result.restoredCount} orders restored to active purchase history.`,
      },
      { headers: NO_CACHE_HEADERS }
    );
  }

  let orderCode: string | null = null;
  const url = request.nextUrl;
  const paramCode = url.searchParams.get("orderCode") || url.searchParams.get("orderId");
  if (paramCode) {
    orderCode = paramCode;
  } else {
    orderCode = body?.orderCode || body?.orderId || null;
  }

  if (!orderCode || typeof orderCode !== "string") {
    return NextResponse.json(
      { success: false, error: "MISSING_ORDER_CODE", message: "orderCode is required." },
      { status: 400, headers: NO_CACHE_HEADERS }
    );
  }

  const result = await CustomerPurchaseService.unarchiveOrder(userId, orderCode.trim());
  if (!result.success) {
    const status = result.code === "MIGRATION_PENDING" || result.error?.includes("migration") ? 503 : 400;
    return NextResponse.json(
      { success: false, error: result.code || "RESTORE_FAILED", message: result.error },
      { status, headers: NO_CACHE_HEADERS }
    );
  }

  return NextResponse.json(
    {
      success: true,
      isArchived: false,
      orderCode: result.orderCode,
      message: "Order restored to active purchase history.",
    },
    { headers: NO_CACHE_HEADERS }
  );
}

